"use client";

import { useState, useEffect } from "react";
import { ArrowRight, Sparkles, ChevronLeft, ChevronRight } from "lucide-react";

const SLIDES = [
  {
    id: 1,
    image: "/images/hero-perfume-1.jpg",
    badge: "Ch? b?n n??c hoa nguy?n chai",
    title: "PERFUME",
    highlight: "ATELIER",
    description: "Kh?m ph? c?c chai n??c hoa fullsize ???c ch?n theo nh?m h??ng r? r?ng, d? d?ng v? ph? h?p kh? h?u Vi?t Nam.",
    gradient: "from-rose-200 to-amber-200"
  },
  {
    id: 2,
    image: "/images/hero-perfume-2.jpg",
    badge: "Nguy?n seal, nguy?n h?p",
    title: "M?i h??ng ch?n chu,",
    highlight: "d?u ?n r?t ri?ng",
    description: "T? floral m?m, woody s?ch ??n amber ?m, m?i s?n ph?m ??u l? chai nguy?n b?n, kh?ng chi?t v? kh?ng k?m ph? ki?n.",
    gradient: "from-cyan-100 to-emerald-200"
  },
  {
    id: 3,
    image: "/images/hero-perfume-3.jpg",
    badge: "B? s?u t?p full bottle",
    title: "Ch?n h??ng theo mood,",
    highlight: "m?c ??p c? ng?y",
    description: "C?c t?ng h??ng ???c m? t? r? ?? b?n ch?n ??ng chai cho v?n ph?ng, h?n h?, d?o ph? hay nh?ng bu?i t?i ??c bi?t.",
    gradient: "from-violet-100 to-rose-200"
  }
];

export default function Hero() {
  const [currentSlide, setCurrentSlide] = useState(0);

  useEffect(() => {
    const timer = setInterval(() => setCurrentSlide((prev) => (prev + 1) % SLIDES.length), 5000);
    return () => clearInterval(timer);
  }, []);

  const handleNext = () => setCurrentSlide((prev) => (prev + 1) % SLIDES.length);
  const handlePrev = () => setCurrentSlide((prev) => (prev - 1 + SLIDES.length) % SLIDES.length);

  const handleScrollTo = (e: React.MouseEvent<HTMLAnchorElement>, targetId: string) => {
    e.preventDefault();
    document.getElementById(targetId)?.scrollIntoView({ behavior: "smooth", block: "start" });
  };

  return (
    <div className="relative w-full max-w-7xl mx-auto mb-12 lg:mb-16 rounded-3xl overflow-hidden h-[calc(100vh-140px)] min-h-[420px] max-h-[640px] flex items-center shadow-2xl group">
      {SLIDES.map((slide, index) => (
        <div key={slide.id} className={`absolute inset-0 transition-opacity duration-1000 ease-in-out ${index === currentSlide ? "opacity-100 z-10" : "opacity-0 z-0"}`}>
          <div className={`absolute inset-0 bg-cover bg-center bg-no-repeat transition-transform duration-[7000ms] ease-out ${index === currentSlide ? "scale-105" : "scale-100"}`} style={{ backgroundImage: `url('${slide.image}')` }} />
          <div className="absolute inset-0 bg-gradient-to-r from-black/75 via-black/45 to-black/10" />
          <div className="absolute inset-0 flex items-center z-20 w-full px-6 md:px-12 lg:px-20 py-12 md:py-0 text-white">
            <div className={`max-w-2xl transition-all duration-1000 delay-300 ${index === currentSlide ? "opacity-100 translate-y-0" : "opacity-0 translate-y-8"}`}>
              <div className="inline-flex items-center gap-2 px-3 py-1.5 rounded-full bg-white/10 backdrop-blur-md border border-white/20 mb-6 text-sm font-medium text-white/90">
                <Sparkles className="w-4 h-4 text-primary" />
                <span>{slide.badge}</span>
              </div>
              <h1 className="text-4xl md:text-5xl lg:text-6xl font-bold leading-[1.1] tracking-normal mb-6 text-balance">
                {slide.title}<br className="hidden md:block" />
                <span className={`text-transparent bg-clip-text bg-gradient-to-r ${slide.gradient}`}>{slide.highlight}</span>
              </h1>
              <p className="text-lg md:text-xl text-white/82 mb-8 max-w-xl text-balance leading-relaxed">{slide.description}</p>
              <div className="flex flex-col sm:flex-row gap-4">
                <a href="#ban-chay" onClick={(e) => handleScrollTo(e, "ban-chay")} className="inline-flex items-center justify-center px-8 py-4 bg-primary text-primary-foreground hover:bg-primary/90 rounded-full font-semibold transition-all shadow-lg hover:-translate-y-1 cursor-pointer">
                  Kh?m ph? ngay
                  <ArrowRight className="ml-2 w-5 h-5" />
                </a>
                <a href="#nuoc-hoa-nu" onClick={(e) => handleScrollTo(e, "nuoc-hoa-nu")} className="inline-flex items-center justify-center px-8 py-4 bg-white/10 hover:bg-white/20 backdrop-blur-md text-white border border-white/20 rounded-full font-semibold transition-all hover:-translate-y-1 cursor-pointer">
                  Xem n??c hoa n?
                </a>
              </div>
            </div>
          </div>
        </div>
      ))}
      <div className="absolute z-30 bottom-8 right-8 flex gap-3 opacity-0 group-hover:opacity-100 transition-opacity duration-300">
        <button onClick={handlePrev} className="p-3 rounded-full bg-black/30 hover:bg-black/50 backdrop-blur-sm text-white border border-white/10 transition-colors" aria-label="Previous slide"><ChevronLeft className="w-5 h-5" /></button>
        <button onClick={handleNext} className="p-3 rounded-full bg-black/30 hover:bg-black/50 backdrop-blur-sm text-white border border-white/10 transition-colors" aria-label="Next slide"><ChevronRight className="w-5 h-5" /></button>
      </div>
      <div className="absolute z-30 bottom-8 left-1/2 -translate-x-1/2 flex gap-2">
        {SLIDES.map((_, index) => (
          <button key={index} onClick={() => setCurrentSlide(index)} className={`w-2.5 h-2.5 rounded-full transition-all duration-500 ${index === currentSlide ? "w-8 bg-primary" : "bg-white/50 hover:bg-white/80"}`} aria-label={`Go to slide ${index + 1}`} />
        ))}
      </div>
    </div>
  );
}
